INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_ADJECTIVE','Muisca');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_ABILITY','The Sacred Exchange');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_ABILITY_HELP','Working an owned, improved, unpillaged Gold or Silver tile grants +2 Faith and +1 Culture. Owning an actual Lake tile within three hexes grants +1 Gold. Each bonus is binary.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_CIV_PEDIA','Inspired by the Muisca network of highland chiefdoms in present-day Colombia and by its salt trade, metalworking and sacred lakes. The uniques are fictionalized gameplay abstractions.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_STRATEGY','Settle near farmable land, mineable resources and sacred lakes. Assign citizens to improved metals and defend hills with Guecha Warriors. Invest resource yields in religion and diplomacy.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_LEADER_PEDIA','Inspired by the Muisca network of highland chiefdoms in present-day Colombia and by its salt trade, metalworking and sacred lakes. The uniques are fictionalized gameplay abstractions.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_DAWN','Inspired by the Muisca network of highland chiefdoms in present-day Colombia and by its salt trade, metalworking and sacred lakes. The uniques are fictionalized gameplay abstractions.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_UNIT','Guecha Warrior');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_UNIT_HELP','+1 Sight and +15% defense on Hills. Both unique bonuses persist through upgrades.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_UNIT_STRATEGY','+1 Sight and +15% defense on Hills. Both unique bonuses persist through upgrades.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_UNIT_PEDIA','+1 Sight and +15% defense on Hills. Both unique bonuses persist through upgrades.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_BUILDING','Salt Exchange');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_BUILDING_HELP','+1 Faith. +1 Gold per worked, owned, unpillaged Mine, capped at +2.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_BUILDING_PEDIA','+1 Faith. +1 Gold per worked, owned, unpillaged Mine, capped at +2.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_BUILDING_STRATEGY','Settle near farmable land, mineable resources and sacred lakes. Assign citizens to improved metals and defend hills with Guecha Warriors. Invest resource yields in religion and diplomacy.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_DUMMY','Internal city yield controller');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_CIV5_HEADING_1','The Muisca Confederation');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_CIV5_TEXT_1','Inspired by the Muisca network of highland chiefdoms in present-day Colombia and by its salt trade, metalworking and sacred lakes. The uniques are fictionalized gameplay abstractions.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_LEADERPAGE_NAME','Zipa Tisquesusa');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_LEADERPAGE_SUBTITLE','The Muisca Confederation');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_LEADERPAGE_HEADING_1','Leadership');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_LEADERPAGE_TEXT_1','Inspired by the Muisca network of highland chiefdoms in present-day Colombia and by its salt trade, metalworking and sacred lakes. The uniques are fictionalized gameplay abstractions.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_FALLBACK_1','We have heard your terms.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_FIRST_GREETING_1','Welcome to Bacatá. You may keep your coins. Tell me what your people consider sacred.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_DECLAREWAR_1','You count our gold and mistake it for weakness. Our warriors count the paths through these mountains.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_DEFEATED_1','The gold will pass from hand to hand. I wonder if you will ever understand what it meant.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D032_ATTACKED_1','Climb, then. The mountains will decide which of us reaches the summit.');
INSERT INTO Diplomacy_Responses(LeaderType,ResponseType,Response,Bias) VALUES ('LEADER_CWC3_D032','RESPONSE_FIRST_GREETING','TXT_KEY_CWC3_D032_FIRST_GREETING_%',1);
INSERT INTO Diplomacy_Responses(LeaderType,ResponseType,Response,Bias) VALUES ('LEADER_CWC3_D032','RESPONSE_DECLAREWAR','TXT_KEY_CWC3_D032_DECLAREWAR_%',1);
INSERT INTO Diplomacy_Responses(LeaderType,ResponseType,Response,Bias) VALUES ('LEADER_CWC3_D032','RESPONSE_DEFEATED','TXT_KEY_CWC3_D032_DEFEATED_%',1);
INSERT INTO Diplomacy_Responses(LeaderType,ResponseType,Response,Bias) VALUES ('LEADER_CWC3_D032','RESPONSE_ATTACKED','TXT_KEY_CWC3_D032_ATTACKED_%',1);
INSERT INTO Diplomacy_Responses SELECT DISTINCT 'LEADER_CWC3_D032',N.ResponseType,'TXT_KEY_CWC3_D032_FALLBACK_%',1 FROM Diplomacy_Responses N WHERE N.LeaderType='LEADER_WASHINGTON' AND NOT EXISTS (SELECT 1 FROM Diplomacy_Responses C WHERE C.LeaderType='LEADER_CWC3_D032' AND C.ResponseType=N.ResponseType);
